insert into public.projects (slug, title, category, role, year, summary, sections, images, tags, status, sort_order)
values
  ('luma', 'Luma Bar 灵光条', 'AI 桌面 Agent', '产品设计 / 核心成员', '2026.07', '让 AI 留在当前工作流里。围绕频繁切窗与上下文中断，设计常驻桌面入口。',
   '[{"title":"核心问题","body":"在多个应用之间寻找内容、复制上下文、切换窗口，会打断当前任务。设计需要让 AI 在恰当的位置出现，并允许用户继续手头的工作。"},{"title":"我的工作","body":"围绕用户场景与技术边界进行需求和竞品分析，输出 PRD、信息架构、用户流程与功能优先级；细化权限确认、任务状态、异常提示与失败恢复。"},{"title":"设计取舍","body":"用低摩擦输入与克制的状态反馈保持主任务连续性；结合上下文就地展开，让用户可以确认行动并返回工作。"},{"title":"交付与成果","body":"与工程、设计成员协同完成可运行原生 Demo。团队获得 AdventureX 2026 亚马逊云科技赛道二等奖。"},{"title":"下一步验证","body":"以任务成功率、响应时延、异常恢复与资源占用为验证指标，比较常驻入口是否真正减少切窗。这些是验证计划，不是已测得的成果数据。"}]',
   '[{"src":"/assets/luma-cover.jpg","alt":"Luma Bar 品牌与产品总览"}]', array['AI 产品','桌面体验','交互系统'], 'published', 10),
  ('meet', '遇见集', 'AI 旅行记录', 'UI 与前端交互设计负责人', '2026.09', '把一次遇见，留成可以再次抵达的记忆。',
   '[{"title":"场景与问题","body":"旅行中的照片、地点与感受容易散落在不同入口。记录需要同时保留个人体验与可以理解、确认的 AI 信息。"},{"title":"我的工作","body":"将流程拆分为采集、AI 理解、用户确认、记录沉淀和地图回看，完成地图首页、记录详情、旅程及设备中心等页面设计与前端协作。"},{"title":"交互判断","body":"详情页将个人“初见”与 AI 博物志分区，补充识别失败、地点未知、人工补充等状态，帮助用户理解并纠正不确定的信息。"},{"title":"协作与成果","body":"与后端、设备接入和部署成员对齐多模态记录流程，参与共同调试与现场展示。团队完成可交互 Demo，获得 AIX Origin 港深黑客松织域 Weave 赛道三等奖。"}]',
   '[{"src":"/assets/meet-map.png","alt":"地图首页与记忆入口"},{"src":"/assets/meet-detail.png","alt":"初见与 AI 博物志详情"}]', array['多模态 AI','移动体验','视觉叙事'], 'published', 20),
  ('drift', 'DriftLearn 流光知', 'AI 微学习', '产品 / 体验设计', '2026.05', '让内容兴趣成为返回学习的入口。',
   '[{"title":"核心问题","body":"针对易分心学习者，拆解“娱乐吸引—学习中断—难以回流”的链路，寻找从内容兴趣返回学习的轻量入口。"},{"title":"设计方案","body":"规划信息流学习卡、语境化单词卡和低压力反馈，保留继续浏览与查看详情的选择，让用户能够轻量看见、深入理解、标记并再次进入。"},{"title":"我的交付","body":"输出核心流程与 Figma 原型，协同推进可体验 Demo，并设计卡片完成率、停留时长与学习回流率等验证指标。"},{"title":"成果与反思","body":"项目获得抖音 AI 创变者计划三等奖、“游园会之星”。点击卡片不等于学会了，下一轮需要验证内容关联和真实学习回流。"}]',
   '[{"src":"/assets/driftlearn-cover.png","alt":"DriftLearn 流光知项目标识"}]', array['AI 学习','内容产品','原型验证'], 'published', 30),
  ('space', '空间研究与系统设计', '建筑 / 视觉叙事', '场地研究与设计表达', '作品选集', '从场地、人群与历史脉络出发，把复杂研究组织成可读的视觉叙事。',
   '[{"title":"惠州府城历史街区","body":"结合历史街区调研、区位肌理、人群活动与气候文脉，建立从研究到更新策略的表达路径。"},{"title":"工业遗产更新","body":"探索既有建筑、公共流线与展示休闲功能的整合。"},{"title":"迁移到 AI 设计","body":"将建筑训练转化为数字产品的信息架构、用户路径与视觉叙事。"}]',
   '[{"src":"/assets/huizhou-research.jpg","alt":"惠州府城历史街区场地研究完整展板"},{"src":"/assets/industrial-service-center.jpg","alt":"工业遗产更新游客服务中心完整展板"}]', array['空间研究','信息组织','视觉表达'], 'published', 40)
